package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.Add;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*;import com.menter.treatmentvault.data.*;import kotlinx.coroutines.launch
@Composable fun SupplyScreen(back:()->Unit){val app=androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication;val dao=app.database.dao();val list by dao.supplies().collectAsState(emptyList());val scope=rememberCoroutineScope();var add by remember{mutableStateOf(false)};Page("药品与用品",back){Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("待购","已购","暂不购买").forEach{s->AssistChip(onClick={},label={Text("$s ${list.count{it.purchaseStatus==s}}")})}};LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.weight(1f)){items(list){v->Card{Column(Modifier.padding(12.dp)){Text(v.name,style=MaterialTheme.typography.titleMedium);Text("${v.purchaseStatus} · ${v.necessity}");if(v.purpose.isNotBlank())Text(v.purpose);if(v.stages.isNotBlank())Text(v.stages,style=MaterialTheme.typography.bodySmall)}}}};Button({add=true},Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Text("新增用品")}}
if(add){var name by remember{mutableStateOf("")};var purpose by remember{mutableStateOf("")};var stages by remember{mutableStateOf("")};AlertDialog(onDismissRequest={add=false},confirmButton={TextButton({if(name.isNotBlank())scope.launch{dao.saveSupply(SupplyEntity(name=name,purpose=purpose,stages=stages));add=false}}){Text("保存")}},dismissButton={TextButton({add=false}){Text("取消")}},title={Text("新增用品")},text={Column{Field(name,{name=it},"名称");Field(stages,{stages=it},"使用阶段");Field(purpose,{purpose=it},"作用")}})} }
